/**
 * FollowUpSuggestionsBar — 追问建议栏组件
 *
 * 在AI回复完成后展示快捷追问选项
 * 支持点击直接发送，支持关闭
 */
import React, { useEffect, useState } from 'react'
import { X, Sparkles, Send } from 'lucide-react'
import { followUpSuggestionEngine, type FollowUpSuggestion } from '../../services/followUpSuggestionService'

interface FollowUpSuggestionsBarProps {
  onSendSuggestion: (question: string) => void
  messages: Array<{ role: string; content: string; id: string }>
  isVisible: boolean
}

function FollowUpSuggestionsBar({ onSendSuggestion, messages, isVisible }: FollowUpSuggestionsBarProps) {
  const [suggestions, setSuggestions] = useState<FollowUpSuggestion[]>([])
  const [isVisibleLocal, setIsVisibleLocal] = useState(false)

  useEffect(() => {
    if (!isVisible || messages.length === 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsVisibleLocal(false)
      return
    }

    // 获取最后一条AI回复
    const lastAssistantMsg = [...messages].reverse().find(m => m.role === 'assistant')
    if (!lastAssistantMsg) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsVisibleLocal(false)
      return
    }

    // 更新上下文
    const content = lastAssistantMsg.content
    const hasFormulaOutput = content.includes('"data-table"') || content.includes('配方')
    const hasSafetyWarning = content.includes('注意事项') || content.includes('warning')

    followUpSuggestionEngine.updateContext({
      hasFormulaOutput,
      hasSafetyWarning,
      messageCount: messages.length,
      topicKeywords: extractKeywords(content),
      entities: extractEntities(content),
    })

    // 生成追问建议
    const sugs = followUpSuggestionEngine.generateSuggestions(3)
    setSuggestions(sugs)
    setIsVisibleLocal(true)
  }, [isVisible, messages])

  if (!isVisibleLocal || suggestions.length === 0) {
    return null
  }

  return (
    <div className="mt-4 mb-2 p-3 bg-gradient-to-r from-primary-50/60 to-secondary-50/40 dark:from-primary-900/10 dark:to-secondary-900/5 border border-primary-200 dark:border-primary-800/40 rounded-xl">
      {/* 标题栏 */}
      <div className="flex items-center justify-between mb-2.5">
        <div className="flex items-center gap-1.5">
          <Sparkles className="w-3.5 h-3.5 text-primary-500" />
          <span className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">
            可以继续追问
          </span>
        </div>
        <button
          onClick={() => setIsVisibleLocal(false)}
          className="p-1 rounded hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors"
        >
          <X className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
        </button>
      </div>

      {/* 追问选项 */}
      <div className="flex flex-wrap gap-2">
        {suggestions.map((sug) => (
          <button
            key={sug.id}
            onClick={() => onSendSuggestion(sug.question)}
            className="group flex items-center gap-1.5 px-3 py-1.5 rounded-lg
              bg-white dark:bg-neutral-800
              border border-neutral-200 dark:border-neutral-700
              hover:border-primary-300 dark:hover:border-primary-600
              hover:shadow-sm transition-all duration-200
              text-left"
          >
            <span className="text-xs px-1.5 py-0.5 rounded bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700 font-medium flex-shrink-0">
              {sug.category}
            </span>
            <span className="text-xs text-neutral-600 dark:text-neutral-400 group-hover:text-neutral-800 dark:group-hover:text-neutral-200 truncate max-w-[200px]">
              {sug.question}
            </span>
            <Send className="w-3 h-3 text-neutral-300 dark:text-neutral-400 group-hover:text-primary-500 flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity" />
          </button>
        ))}
      </div>

      {/* 手动输入提示 */}
      <div className="mt-2 text-xs text-neutral-400 dark:text-neutral-400">
        或直接输入您的问题...
      </div>
    </div>
  )
}

/**
 * 从内容中提取关键词
 */
function extractKeywords(content: string): string[] {
  const keywords: string[] = []
  const patterns = [
    /高血糖|血糖|糖尿病/i,
    /睡眠|失眠|安神/i,
    /血压|心血管/i,
    /免疫|抗氧化/i,
    /肝|肾|护肝/i,
    /减肥|血脂|代谢/i,
    /补气|养血|滋补/i,
    /配方|药食同源/i,
    /桑叶|苦瓜|枸杞/i,
  ]
  for (const pattern of patterns) {
    if (pattern.test(content)) {
      const match = content.match(pattern)
      if (match) keywords.push(match[0])
    }
  }
  return keywords
}

/**
 * 从内容中提取实体
 */
function extractEntities(content: string): string[] {
  const entities: string[] = []
  const knownEntities = [
    '黄芪', '党参', '枸杞', '人参', '桑叶', '苦瓜', '肉桂', '葛根',
    '茯苓', '山药', '红枣', '菊花', '决明子', '荷叶', '山楂',
  ]
  for (const entity of knownEntities) {
    if (content.includes(entity)) {
      entities.push(entity)
    }
  }
  return entities
}

export default FollowUpSuggestionsBar

/**
 * TypewriterText — 打字机动画组件
 *
 * 逐字显示 AI 回复内容，模拟实时生成效果。
 * 支持：
 * - 可调速度
 * - 完成回调
 * - Markdown 兼容（逐块渲染）
 * - 跳跃完成（点击加速）
 */
import React, { useState, useEffect, useRef, useCallback } from 'react'
import MarkdownRenderer from './MarkdownRenderer'

interface TypewriterTextProps {
  content: string
  speed?: number        // 每字毫秒数（默认 30）
  chunkSize?: number     // 每次显示字数（默认 3）
  onComplete?: () => void
  enabled?: boolean      // 是否启用动画（默认 true）
}

export default function TypewriterText({
  content: rawContent,
  speed = 30,
  chunkSize = 3,
  onComplete,
  enabled = true,
}: TypewriterTextProps) {
  // 防御：上游（如 MessageBubble）在消息 content 字段缺失时会传入 null/undefined。
  // 若不在此归一化，下方 :47 的 content.length 会抛 TypeError。
  const content = rawContent ?? ''
  // Respect user's motion preference
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(() => {
    if (typeof window !== 'undefined' && window.matchMedia) {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches
    }
    return false
  })

  // Listen for changes to the reduced motion preference
  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const handler = (e: MediaQueryListEvent | MediaQueryList) => setPrefersReducedMotion(e.matches)
    mq.addEventListener('change', handler as EventListener)
    return () => mq.removeEventListener('change', handler as EventListener)
  }, [])

  // 长内容自动跳过动画 — 避免不完整 Markdown 渲染导致内容丢失
  const isLongContent = content.length > 800
  const autoComplete = !enabled || isLongContent || prefersReducedMotion
  const [displayedLen, setDisplayedLen] = useState(autoComplete ? content.length : 0)
  const [isComplete, setIsComplete] = useState(autoComplete)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const completedRef = useRef(false)

  // 点击跳过动画
  const skipToEnd = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current)
    setDisplayedLen(content.length)
    setIsComplete(true)
    if (!completedRef.current) {
      completedRef.current = true
      onComplete?.()
    }
  }, [content.length, onComplete])

  useEffect(() => {
    if (!enabled || !content || isLongContent) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setDisplayedLen(content.length)
      setIsComplete(true)
      return
    }

    // 重置
    setDisplayedLen(0)
    setIsComplete(false)
    completedRef.current = false

    // 动态速度: 内容越长速度越快
    const adaptiveChunkSize = content.length > 300 ? 8 : content.length > 100 ? 5 : chunkSize

    timerRef.current = setInterval(() => {
      setDisplayedLen(prev => {
        const next = prev + adaptiveChunkSize
        if (next >= content.length) {
          clearInterval(timerRef.current!)
          setIsComplete(true)
          // 延迟回调确保状态更新
          setTimeout(() => {
            if (!completedRef.current) {
              completedRef.current = true
              onComplete?.()
            }
          }, 50)
          return content.length
        }
        return next
      })
    }, speed)

    return () => {
      if (timerRef.current) clearInterval(timerRef.current)
    }
  }, [content, enabled, speed, chunkSize, onComplete])

  // 计算百分比
  const progress = content.length > 0 ? (displayedLen / content.length) * 100 : 100

  // 不做动画时直接渲染
  if (!enabled || isComplete) {
    return (
      <div  role="button" tabIndex={0} onClick={skipToEnd} className="cursor-default">
        <MarkdownRenderer content={content} />
      </div>
    )
  }

  // 逐字模式：渲染已显示的部分
  const visibleText = content.slice(0, displayedLen)

  return (
    <div  role="button" tabIndex={0} onClick={skipToEnd} className="cursor-default group relative">
      <MarkdownRenderer content={visibleText} />

      {/* 闪烁光标 */}
      {displayedLen < content.length && (
        <span className="inline-block w-0.5 h-4 bg-primary-500 animate-pulse ml-0.5 align-text-bottom" />
      )}

      {/* 进度条（极简） */}
      {displayedLen < content.length && (
        <div className="h-0.5 bg-neutral-200 dark:bg-neutral-700 rounded-full mt-2 overflow-hidden opacity-0 group-hover:opacity-100 transition-opacity">
          <div
            className="h-full bg-primary-400 rounded-full transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
      )}
    </div>
  )
}
